<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, key } from '../api.js'
const appointments=ref([]),catalog=ref([]),selected=ref(null),busy=ref(false),message=ref(''),failed=ref(false)
const record=reactive({chiefComplaint:'',examination:'',assessment:'',treatmentNote:'',advice:'',followUpDate:'',itemId:'',quantity:1})
async function refresh(){try{const [a,c]=await Promise.all([api.get('/doctor/appointments'),api.get('/doctor/treatment-items')]);appointments.value=a.items;catalog.value=c.items}catch(e){message.value=e.message;failed.value=true}}
async function act(task){busy.value=true;failed.value=false;try{await task();message.value='操作成功';await refresh()}catch(e){message.value=e.message;failed.value=true}finally{busy.value=false}}
async function submit(){if(!selected.value)return;const body={chiefComplaint:record.chiefComplaint,examination:record.examination,assessment:record.assessment,treatmentNote:record.treatmentNote,advice:record.advice,items:record.itemId?[{itemId:String(record.itemId),quantity:String(record.quantity)}]:[]};if(record.followUpDate)body.followUpDate=record.followUpDate;await act(()=>api.post(`/doctor/appointments/${selected.value.id}/medical-record/submit`,body,{headers:{'Idempotency-Key':key()}}));selected.value=null}
const time=value=>value?new Date(value.endsWith('Z')?value:value+'Z').toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):''
onMounted(refresh)
</script>
<template>
  <h1>医生工作台</h1><p class="status" :class="{error:failed}" role="status" aria-live="polite">{{ message }}</p><section class="panel"><h2>今日预约</h2><p v-if="!appointments.length">今日暂无预约。</p><div v-for="a in appointments" :key="a.id" class="record"><strong>预约 {{ a.appointment_no }} · {{ a.status }}</strong><small>{{ time(a.starts_at) }} · ID {{ a.id }}</small><div class="row"><button v-if="a.status==='CHECKED_IN'" type="button" class="quiet" :disabled="busy" @click="act(()=>api.put(`/doctor/appointments/${a.id}/call`))">叫号</button><button v-if="a.status==='CHECKED_IN'" type="button" class="primary" :disabled="busy" @click="act(()=>api.put(`/doctor/appointments/${a.id}/start`))">开始接诊</button><button v-if="a.status==='IN_VISIT'" type="button" class="primary" @click="selected=a">填写记录</button></div></div></section>
  <section v-if="selected" class="panel"><form aria-labelledby="record-heading" action="/hospital/api/doctor/appointments" method="post" @submit.prevent="submit"><h2 id="record-heading">就诊记录 · 预约 {{ selected.id }}</h2><div class="grid"><div><label for="complaint">主诉</label><textarea id="complaint" v-model.trim="record.chiefComplaint" name="chiefComplaint" maxlength="2000" required></textarea><label for="examination">检查结果</label><textarea id="examination" v-model.trim="record.examination" name="examination" maxlength="2000" required></textarea><label for="assessment">诊断评估</label><textarea id="assessment" v-model.trim="record.assessment" name="assessment" maxlength="2000"></textarea></div><div><label for="treatment-note">处理过程</label><textarea id="treatment-note" v-model.trim="record.treatmentNote" name="treatmentNote" maxlength="2000"></textarea><label for="advice">医嘱</label><textarea id="advice" v-model.trim="record.advice" name="advice" maxlength="2000" required></textarea><label for="follow-up">建议复诊日期</label><input id="follow-up" v-model="record.followUpDate" name="followUpDate" type="date"></div></div><fieldset><legend>诊疗收费项目（可选）</legend><label for="item">项目</label><select id="item" v-model="record.itemId" name="itemId"><option value="">无</option><option v-for="i in catalog" :key="i.id" :value="i.id">{{ i.name }} · {{ i.fee }} 元</option></select><label for="quantity">数量</label><input id="quantity" v-model.number="record.quantity" name="quantity" type="number" min="1" max="20"></fieldset><button class="primary" type="submit" :disabled="busy">提交记录并完成接诊</button></form></section>
</template>
<style scoped>.record small{display:block}.record button{margin-top:.5rem}fieldset{border:1px solid #c8d9de;border-radius:8px;margin:1rem 0;padding:1rem}</style>
